CREATE TABLE IF NOT EXISTS platform_identity (singleton INTEGER PRIMARY KEY CHECK(singleton=1), node_id TEXT NOT NULL, incarnation TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS platform_migration (name TEXT PRIMARY KEY, sha256 TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS platform_audit (seq INTEGER PRIMARY KEY, origin_node_id TEXT NOT NULL, origin_incarnation TEXT NOT NULL, at TEXT NOT NULL, event_id TEXT NOT NULL UNIQUE, envelope BLOB NOT NULL, entry_hash TEXT NOT NULL) STRICT;
CREATE TRIGGER IF NOT EXISTS platform_audit_no_update BEFORE UPDATE ON platform_audit BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TRIGGER IF NOT EXISTS platform_audit_no_delete BEFORE DELETE ON platform_audit BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TABLE IF NOT EXISTS platform_command_ledger (actor_ref TEXT NOT NULL, command_key TEXT NOT NULL, identity BLOB NOT NULL, receipt BLOB NOT NULL, status INTEGER NOT NULL, resource_ref TEXT, result_code TEXT NOT NULL, safe_body BLOB, PRIMARY KEY(actor_ref,command_key)) STRICT;
CREATE TRIGGER IF NOT EXISTS platform_ledger_no_update BEFORE UPDATE ON platform_command_ledger BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TRIGGER IF NOT EXISTS platform_ledger_no_delete BEFORE DELETE ON platform_command_ledger BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TABLE IF NOT EXISTS platform_command_intent (actor_ref TEXT NOT NULL, command_key TEXT NOT NULL, identity BLOB NOT NULL, intent_id TEXT NOT NULL UNIQUE, resume_handler TEXT NOT NULL, input_ref TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(actor_ref,command_key)) STRICT;
CREATE TABLE IF NOT EXISTS platform_schedule (key TEXT PRIMARY KEY, generation INTEGER NOT NULL, job BLOB NOT NULL, due TEXT, completed INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE IF NOT EXISTS platform_evaluation_pending (completion_id TEXT PRIMARY KEY, value BLOB NOT NULL, first_failed_at TEXT NOT NULL, attempts INTEGER NOT NULL, fault_code TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS platform_evaluation_completed (completion_id TEXT PRIMARY KEY) STRICT;
CREATE TABLE IF NOT EXISTS platform_private_reference (seq INTEGER PRIMARY KEY, entry_id TEXT NOT NULL UNIQUE, version_id TEXT NOT NULL UNIQUE, record_kind TEXT NOT NULL, owner_person_id TEXT NOT NULL, command_key TEXT NOT NULL, fingerprint TEXT NOT NULL, key_id TEXT NOT NULL, ciphertext_sha256 TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE IF NOT EXISTS platform_private_deletion (actor_ref TEXT NOT NULL, command_key TEXT NOT NULL, identity BLOB NOT NULL, owner_person_id TEXT NOT NULL, entry_ids BLOB NOT NULL, revocation_id TEXT, completed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(actor_ref,command_key)) STRICT;
CREATE TABLE IF NOT EXISTS platform_task (task_id TEXT PRIMARY KEY, input BLOB NOT NULL, job_id TEXT UNIQUE, state TEXT NOT NULL, progress TEXT NOT NULL, generation INTEGER NOT NULL, attempts INTEGER NOT NULL, worker_id TEXT, expires TEXT, result_ref TEXT, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS repl_log (seq INTEGER PRIMARY KEY, origin_node_id TEXT NOT NULL, origin_incarnation TEXT NOT NULL, change BLOB NOT NULL, prev_hash TEXT NOT NULL, entry_hash TEXT NOT NULL) STRICT;
CREATE TRIGGER IF NOT EXISTS repl_log_no_update BEFORE UPDATE ON repl_log BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TRIGGER IF NOT EXISTS repl_log_no_delete BEFORE DELETE ON repl_log BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TABLE IF NOT EXISTS platform_replica_stream (stream_id TEXT PRIMARY KEY, recipient_id TEXT NOT NULL, purpose TEXT NOT NULL, policy_epoch INTEGER NOT NULL, scan_seq INTEGER NOT NULL, delivery_seq INTEGER NOT NULL, ack_seq INTEGER NOT NULL, fenced INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE IF NOT EXISTS platform_replica_delivery (stream_id TEXT NOT NULL, seq INTEGER NOT NULL, envelope BLOB NOT NULL, envelope_sha256 TEXT NOT NULL, PRIMARY KEY(stream_id,seq)) STRICT;
CREATE TABLE IF NOT EXISTS platform_replica_applied (stream_id TEXT NOT NULL, seq INTEGER NOT NULL, envelope_sha256 TEXT NOT NULL, PRIMARY KEY(stream_id,seq)) STRICT;
CREATE TABLE IF NOT EXISTS platform_revocation (control_id TEXT PRIMARY KEY, control BLOB NOT NULL, acknowledged INTEGER NOT NULL DEFAULT 0, recipient_id TEXT NOT NULL, stream_id TEXT NOT NULL, old_epoch INTEGER NOT NULL, UNIQUE(recipient_id,stream_id,old_epoch)) STRICT;
CREATE TABLE IF NOT EXISTS platform_ownership (kind TEXT NOT NULL, resource_id TEXT NOT NULL, head BLOB NOT NULL, fenced INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(kind,resource_id)) STRICT;
CREATE TABLE IF NOT EXISTS platform_transfer (transfer_id TEXT PRIMARY KEY, transfer BLOB NOT NULL, phase TEXT NOT NULL, certificate BLOB NOT NULL, resource_kind TEXT NOT NULL, resource_id TEXT NOT NULL, epoch INTEGER NOT NULL, UNIQUE(resource_kind,resource_id,epoch)) STRICT;
CREATE TABLE IF NOT EXISTS platform_task_attempt (task_id TEXT NOT NULL REFERENCES platform_task(task_id), generation INTEGER NOT NULL, worker_id TEXT NOT NULL, lease BLOB NOT NULL, PRIMARY KEY(task_id,generation)) STRICT;
CREATE TRIGGER IF NOT EXISTS platform_task_attempt_no_update BEFORE UPDATE ON platform_task_attempt BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TRIGGER IF NOT EXISTS platform_task_attempt_no_delete BEFORE DELETE ON platform_task_attempt BEGIN SELECT RAISE(ABORT, 'append only'); END;

CREATE TABLE IF NOT EXISTS platform_reference (record_type TEXT NOT NULL, record_id TEXT NOT NULL, PRIMARY KEY(record_type,record_id)) STRICT;
CREATE TRIGGER IF NOT EXISTS platform_reference_no_update BEFORE UPDATE ON platform_reference BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TRIGGER IF NOT EXISTS platform_reference_no_delete BEFORE DELETE ON platform_reference BEGIN SELECT RAISE(ABORT, 'append only'); END;
CREATE TABLE IF NOT EXISTS platform_idempotency (actor_ref TEXT NOT NULL, command_key TEXT NOT NULL, safe_body BLOB NOT NULL, expires_at TEXT NOT NULL, PRIMARY KEY(actor_ref,command_key)) STRICT;
